import com.neonshift.app.*;import java.time.*;import java.math.*;import java.util.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;
public class MarkenBillingTest{
 static int checks;static void eq(Object a,Object b){checks++;if(!a.equals(b))throw new AssertionError(a+" != "+b);}
 public static void main(String[] args)throws Exception{
  List<MarkenBilling.Entry> rows=new ArrayList<>();String[] end={"15:00","16:17","16:04"};long[] expected={0,4620000,3840000};List<InvoiceEngine.Item> items=new ArrayList<>();
  for(int n=0;n<3;n++){LocalDate date=LocalDate.of(2026,11,18).plusDays(n);long raw=java.time.Duration.between(LocalTime.of(7,0),LocalTime.parse(end[n])).toMillis();long[] bands=MarkenEngine.bands(date,raw,0);eq(bands[0],27000000L);eq(bands[1],expected[n]);eq(bands[2],0L);MarkenBilling.Entry e=new MarkenBilling.Entry(date.toString(),"07:00",end[n],"Adelaide","Cladding","Marken - UPS Healthcare",1800000,bands[0],bands[1],bands[2],"33.50");rows.add(e);String paid=new BigDecimal(MarkenEngine.paid(raw)).divide(new BigDecimal("3600000"),12,RoundingMode.HALF_UP).toPlainString();String premium=new BigDecimal(bands[1]).multiply(new BigDecimal("33.50")).divide(new BigDecimal("7200000"),12,RoundingMode.HALF_UP).toPlainString();items.add(new InvoiceEngine.Item(date.toString(),e.site,paid,"33.50","source-"+n,premium,true,"PRIVATE TIME DATA"));}
  MarkenBilling.Group group=MarkenBilling.groups(rows).get(0);eq(MarkenBilling.duration(group.ms[0]),"22:30");eq(MarkenBilling.duration(group.ms[1]),"2:21");eq(group.amount(0).toPlainString(),"753.75");eq(group.amount(1).toPlainString(),"118.09");eq(MarkenBilling.total(rows).toPlainString(),"871.84");
  List<MarkenBilling.Entry> fractional=new ArrayList<>();for(int n=0;n<3;n++)fractional.add(new MarkenBilling.Entry("2026-11-18","15:00","15:01","Site","Picker","Marken",0,0,60000,0,"33.50"));eq(MarkenBilling.total(fractional).toPlainString(),"2.51");
  Map<String,String> profile=new HashMap<>();profile.put("name","Example Worker");profile.put("client","Marken - UPS Healthcare");profile.put("description","Cladding services");profile.put("timesheet_position","Cladding");profile.put("timesheet_location","Adelaide");profile.put("bank","Example Bank");profile.put("account_name","Example Worker");profile.put("bsb","000-000");profile.put("account","00000000");
  byte[] sheet=InvoicePdf.generateTimesheet(1,LocalDate.of(2026,11,22),profile,rows),invoice=InvoicePdf.generate(1,LocalDate.of(2026,11,22),profile,items,true);String detailed=new String(sheet,StandardCharsets.ISO_8859_1),simple=new String(invoice,StandardCharsets.ISO_8859_1);
  for(String token:new String[]{"TIMESHEET","07:00","16:17","16:04","22:30","2:21","33.50","50.25","67.00","871.84","Signature:"})eq(detailed.contains(token),true);
  for(String token:new String[]{"07:00","16:17","22:30","2:21","PRIVATE TIME DATA","OT1.5","Signature:"})eq(simple.contains(token),false);eq(simple.contains("871.84"),true);eq(simple.contains("Service period"),true);
  eq(simple.contains("Picking and packing services"),true);eq(detailed.contains("Picking and packing"),true);eq(simple.contains("Cladding"),false);eq(detailed.contains("Cladding"),false);
  Files.createDirectories(Paths.get("build/qa"));Files.write(Paths.get("build/qa/marken-timesheet-reference.pdf"),sheet);Files.write(Paths.get("build/qa/marken-invoice-reference.pdf"),invoice);
  // Multiple pages must keep totals/signature readable without dropping any entries.
  List<MarkenBilling.Entry> many=new ArrayList<>();for(int n=0;n<60;n++)many.add(rows.get(n%3));byte[] multiple=InvoicePdf.generateTimesheet(2,LocalDate.of(2026,11,22),profile,many);eq(new String(multiple,StandardCharsets.ISO_8859_1).contains("/Count 1 "),false);Files.write(Paths.get("build/qa/marken-timesheet-multipage.pdf"),multiple);
  System.out.println("PASS: "+checks+" attachment-reference assertions: 753.75 + 118.09 = 871.84; separate detailed timesheet and invoice without hours.");
 }
}
